// ===== p243 : le songe du gramoun a de la vraie musique d'aujourd'hui — devant les boîtes de nuit du front de mer de Saint-Pierre,
// la musique de la boîte la plus proche (Pixabay) : afrobeat (« Satisfied », kamhunt) pour l'électro et la 4 voies de nuit, salsa (« Happy Latin Salsa Dance », kornevmusic)
// pour le disco, reggae (« Locust », brotheration_records) pour le dancehall. Le séga mauricien et le maloya gardent leurs rythmes. =====
Object.assign(MUS237.b64,{"afro": "", "salsa": "", "reggae": ""});
const CLUB243={electro:'afro',disco:'salsa',dancehall:'reggae'};
function clubSon243(AC,dest,style){const k=CLUB243[style];if(!k||!MUS237.b64[k])return null;let arr=false,src=null;const g=AC.createGain();g.gain.value=0;g.connect(dest);
 const s=atob(MUS237.b64[k]),u=new Uint8Array(s.length);for(let i=0;i<s.length;i++)u[i]=s.charCodeAt(i);
 AC.decodeAudioData(u.buffer).then(b=>{if(arr)return;src=AC.createBufferSource();src.buffer=b;src.loop=true;src.connect(g);src.start();g.gain.linearRampToValueAtTime(1.6,AC.currentTime+1.2)}).catch(()=>{});
 return {s:style,stop(){arr=true;try{g.gain.cancelScheduledValues(AC.currentTime);g.gain.setValueAtTime(g.gain.value,AC.currentTime);g.gain.linearRampToValueAtTime(0,AC.currentTime+.8);setTimeout(()=>{try{src&&src.stop()}catch(e){}},900)}catch(e){}}}}
clubSon243.a=s=>!!CLUB243[s];
try{const g=ANN217.find(g=>/petits jeux/.test(g.g));if(g)g.L.push(['Le songe : électro','« Satisfied », kamhunt (Pixabay).','mus:afro'],['Le songe : disco','« Happy Latin Salsa Dance », kornevmusic (Pixabay).','mus:salsa'],['Le songe : dancehall','« Locust », brotheration_records (Pixabay).','mus:reggae'])}catch(e){}
